634:/// The pass loop, shared by every route. `run` executes one retry pass
635:/// with the prepared arguments (the retry-only set and the pass label
636:/// already threaded in) and returns that pass's result.
637:///
638:/// 2026-10-07 defect (b): Ctrl-C during the retry wait or a retry pass
639:/// stops the retries instead of killing the process, so the route still
640:/// prints the report of the pass that already ran — its deletions
641:/// included — and exits [`INTERRUPTED_EXIT`]. Once the handler has been
642:/// installed, a later Ctrl-C exits at once, as the default did.
643:pub(crate) async fn run_retry_passes<F, Fut>(
644:    args: &TransferArgs,
645:    main: PassFailures,
646:    run: F,
647:) -> Result<RetryOutcome>
648:where
649:    F: FnMut(TransferArgs) -> Fut,
650:    Fut: Future<Output = Result<PassResult>>,
651:{
652:    let armed = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
653:    let interrupt = {
654:        let armed = std::sync::Arc::clone(&armed);
655:        async move {
656:            armed.store(true, std::sync::atomic::Ordering::Relaxed);
657:            if tokio::signal::ctrl_c().await.is_err() {
658:                // No handler could be installed: never interrupt.
659:                std::future::pending::<()>().await;
660:            }
661:        }
662:    };
663:    let outcome = run_retry_passes_until(args, main, run, interrupt).await;
664:    if armed.load(std::sync::atomic::Ordering::Relaxed) {
665:        tokio::spawn(async {
666:            if tokio::signal::ctrl_c().await.is_ok() {
667:                std::process::exit(i32::from(INTERRUPTED_EXIT));
668:            }
669:        });
670:    }
671:    outcome
672:}
